// createFileRefFromBytes through real stacks: a write handler and a job each
// store generated bytes, then the regular download route serves them.

import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import * as z from "zod";
import { selectMany } from "../../bun-db/index.js";
import { entityEventName } from "../../db/index.js";
import { createEntity, createFileField, defineFeature } from "../../engine/index.js";
import { loadAggregate } from "../../event-store/index.js";
import {
  createTestUser,
  setupTestStack,
  type TestStack,
  testTenantId,
  unsafeCreateEntityTable,
} from "../../stack/index.js";
import { createFileRefFromBytes } from "../create-file-ref-from-bytes.js";
import { createFilesFeature } from "../feature.js";
import { fileRefsTable } from "../file-ref-table.js";
import { createInMemoryFileProvider, type InMemoryFileProvider } from "../in-memory-provider.js";

const FILE_REF_CREATED = entityEventName("fileRef", "created");

const PNG_BYTES = new Uint8Array([
  0x89,
  0x50,
  0x4e,
  0x47,
  0x0d,
  0x0a,
  0x1a,
  0x0a,
  ...Array(10).fill(0),
]);
const PDF_BYTES = new TextEncoder().encode("%PDF-1.4 generated");

const reportEntity = createEntity({
  table: "file_ref_from_bytes_reports",
  fields: {
    // accept + maxSize are enforced exactly like on POST /files
    scan: createFileField({ maxSize: "1kb", accept: ["png"] }),
  },
});

let jobStoredIds: string[] = [];
let jobStoreFailure: string | undefined;

const fixtureFeature = defineFeature("file-ref-from-bytes-fixture", (r) => {
  r.entity("report", reportEntity);

  r.writeHandler(
    "store",
    z.object({
      fileName: z.string(),
      mimeType: z.string(),
      bytes: z.array(z.number()),
      attachTo: z
        .object({
          entityType: z.string(),
          fieldName: z.string(),
          entityId: z.string().optional(),
        })
        .optional(),
    }),
    (event, ctx) =>
      createFileRefFromBytes(ctx, {
        fileName: event.payload.fileName,
        mimeType: event.payload.mimeType,
        data: Uint8Array.from(event.payload.bytes),
        ...(event.payload.attachTo ? { attachTo: event.payload.attachTo } : {}),
      }),
    { access: { openToAll: { reason: "test fixture: every signed-in user may store bytes" } } },
  );

  r.job("store-from-job", { trigger: { manual: true }, retries: 0 }, async (_payload, ctx) => {
    const result = await createFileRefFromBytes(
      { ...ctx, user: ctx.systemUser },
      { fileName: "job-report.pdf", mimeType: "application/pdf", data: PDF_BYTES },
    );
    if (result.isSuccess) jobStoredIds.push(result.data.id);
    else jobStoreFailure = result.error.message;
  });
});

let stack: TestStack;
let provider: InMemoryFileProvider;

const tenantA = testTenantId(1);
const tenantB = testTenantId(2);
const userA = createTestUser({ id: 1, tenantId: tenantA, roles: ["Admin"] });
const userB = createTestUser({ id: 2, tenantId: tenantB, roles: ["Admin"] });

beforeAll(async () => {
  provider = createInMemoryFileProvider();
  stack = await setupTestStack({
    features: [createFilesFeature(), fixtureFeature],
    files: { storageProvider: provider },
    jobs: { consumerLane: "worker" },
  });
  await unsafeCreateEntityTable(stack.db, reportEntity);
});

afterAll(async () => {
  await stack.cleanup();
});

let fileRefCountBeforeTest = 0;

async function countTenantAFileRefs(): Promise<number> {
  return (await selectMany(stack.db, fileRefsTable, { tenantId: tenantA })).length;
}

beforeEach(async () => {
  provider.clear();
  fileRefCountBeforeTest = await countTenantAFileRefs();
  jobStoredIds = [];
  jobStoreFailure = undefined;
});

type Stored = { id: string; fileName: string; mimeType: string; size: number; storageKey: string };

function store(
  user: typeof userA,
  payload: {
    fileName: string;
    mimeType: string;
    bytes: Uint8Array;
    attachTo?: { entityType: string; fieldName: string; entityId?: string };
  },
): Promise<Stored> {
  return stack.http.writeOk<Stored>(
    "file-ref-from-bytes-fixture:write:store",
    { ...payload, bytes: [...payload.bytes] },
    user,
  );
}

async function storeErr(
  payload: Parameters<typeof store>[1],
): ReturnType<typeof stack.http.writeErr> {
  return stack.http.writeErr(
    "file-ref-from-bytes-fixture:write:store",
    { ...payload, bytes: [...payload.bytes] },
    userA,
  );
}

async function download(user: typeof userA, id: string): Promise<Response> {
  const token = await stack.jwt.sign(user);
  return stack.app.request(`/api/files/${id}`, { headers: { Authorization: `Bearer ${token}` } });
}

async function expectNothingStored(): Promise<void> {
  expect(await countTenantAFileRefs()).toBe(fileRefCountBeforeTest);
  expect(provider.keys()).toHaveLength(0);
}

describe("createFileRefFromBytes from a write handler", () => {
  test("PNG and PDF are served back with their bytes and content type", async () => {
    const png = await store(userA, {
      fileName: "scan.png",
      mimeType: "image/png",
      bytes: PNG_BYTES,
    });
    const pdf = await store(userA, {
      fileName: "report.pdf",
      mimeType: "application/pdf",
      bytes: PDF_BYTES,
    });

    const pngRes = await download(userA, png.id);
    expect(pngRes.status).toBe(200);
    expect(pngRes.headers.get("Content-Type")).toBe("image/png");
    expect(new Uint8Array(await pngRes.arrayBuffer())).toEqual(PNG_BYTES);

    const pdfRes = await download(userA, pdf.id);
    expect(pdfRes.status).toBe(200);
    expect(pdfRes.headers.get("Content-Type")).toBe("application/pdf");
    expect(new Uint8Array(await pdfRes.arrayBuffer())).toEqual(PDF_BYTES);

    expect(pdf.size).toBe(PDF_BYTES.byteLength);
    expect(pdf.storageKey.startsWith(`${tenantA}/`)).toBe(true);
  });

  test("emits fileRef.created and persists the pointer, not the binary", async () => {
    const pdf = await store(userA, {
      fileName: "report.pdf",
      mimeType: "application/pdf",
      bytes: PDF_BYTES,
    });

    const events = await loadAggregate(stack.db, pdf.id, tenantA);
    const created = events.find((e) => e.type === FILE_REF_CREATED);
    expect(created?.payload["storageKey"]).toBe(pdf.storageKey);
    expect(created?.payload["bytes"]).toBeUndefined();
    const rows = await selectMany(stack.db, fileRefsTable, { id: pdf.id });
    expect(rows).toHaveLength(1);
  });

  test("a user of another tenant gets 404 for the file", async () => {
    const pdf = await store(userA, {
      fileName: "report.pdf",
      mimeType: "application/pdf",
      bytes: PDF_BYTES,
    });

    expect((await download(userB, pdf.id)).status).toBe(404);
  });

  test("oversized file for a field with maxSize is rejected with 422 and leaves nothing behind", async () => {
    const err = await storeErr({
      fileName: "big.png",
      mimeType: "image/png",
      bytes: new Uint8Array([...PNG_BYTES, ...new Uint8Array(2048)]),
      attachTo: { entityType: "report", fieldName: "scan" },
    });

    expect(err.httpStatus).toBe(422);
    expect(JSON.stringify(err.details)).toContain("file_too_large");
    await expectNothingStored();
  });

  test("extension outside the field's accept list is rejected", async () => {
    const err = await storeErr({
      fileName: "report.pdf",
      mimeType: "application/pdf",
      bytes: PDF_BYTES,
      attachTo: { entityType: "report", fieldName: "scan" },
    });

    expect(err.httpStatus).toBe(422);
    await expectNothingStored();
  });

  test("path-traversal identifiers are rejected", async () => {
    const err = await storeErr({
      fileName: "scan.png",
      mimeType: "image/png",
      bytes: PNG_BYTES,
      attachTo: { entityType: "report", fieldName: "scan", entityId: "../other-tenant" },
    });

    expect(err.httpStatus).toBe(422);
    expect(JSON.stringify(err.details)).toContain("invalid_entityId");
    await expectNothingStored();
  });

  test("an attach target that is no registered file field is rejected", async () => {
    const err = await storeErr({
      fileName: "scan.png",
      mimeType: "image/png",
      bytes: PNG_BYTES,
      attachTo: { entityType: "report", fieldName: "doesNotExist" },
    });

    expect(err.httpStatus).toBe(422);
    expect(JSON.stringify(err.details)).toContain("unresolvable_field");
    await expectNothingStored();
  });
});

describe("createFileRefFromBytes from a job", () => {
  test("stores the file in the job's tenant", async () => {
    await stack.jobRunner?.dispatch("file-ref-from-bytes-fixture:job:store-from-job", {
      tenantId: tenantA,
    });

    await stack.drainJobs();

    expect(jobStoreFailure).toBeUndefined();
    expect(jobStoredIds).toHaveLength(1);
    const id = jobStoredIds[0] ?? "";
    const res = await download(userA, id);
    expect(res.status).toBe(200);
    expect(res.headers.get("Content-Type")).toBe("application/pdf");
    expect((await download(userB, id)).status).toBe(404);
  });
});
